def transfer_checked(accounts, src, dst, amount):
    before = sum(accounts.values())
    result = transfer_buggy(dict(accounts), src, dst, amount)
    after = sum(result.values())
    assert after == before, f"money not conserved: before={before} after={after}"
    return result

